window.DIGEST.foryou.push(...[{"id": "2112915106799427957", "url": "https://x.com/Joyingeth/status/2112915106799427957", "text": "THIS GUY OPENED OBSIDIAN AND SAW HIS ENTIRE KNOWLEDGE AS A NETWORK AND HE BUILT IT IN 90 DAYS\n\none note at a time and one link at a time\n\nnow the graph shows him what he actually thinks about and not what he assumed he cared about. Anthropic connects to Claude. Claude connects to GPT-4. GPT-4 connects to Llama. every company, every model, every benchmark, every paper linked by what they share and where they differ\n\nsix months ago he had 200 isolated notes sitting in folders nobody visits\n\ntoday every idea he has connects to something he wrote in the past\n\na thought from january becomes context for a decision in may without him remembering january even happened\n\nhis coworkers are still searching for files by name and finding nothing useful\n\nthe only difference is he stopped filing and started linking\n\nhis notes are not stored they are connected\n\nlike & bookmark this if you’ve been using obsidian as a filing cabinet this whole time", "name": "Joying.eth", "handle": "Joyingeth", "avatar": "https://pbs.twimg.com/profile_images/2101106513750462464/lABHvjzq_200x200.jpg", "likes": 33, "rts": 2, "replies": 1, "views": 1849, "ts": 1792593192, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112915066081165313/vid/avc1/576x320/GkifnTNazQ-SrZmI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112915066081165313/vid/avc1/576x320/GkifnTNazQ-SrZmI.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112915066081165313/img/X3AIFBhRJH3UfTZR.jpg", "dur": 32}], "quote": {"id": "2058492014413447196", "url": "https://x.com/ridark_eth/status/2058492014413447196", "text": "", "name": "Ridark", "handle": "ridark_eth", "avatar": "https://pbs.twimg.com/profile_images/1961150036030455808/2thpdxOr_200x200.jpg", "likes": 397, "rts": 73, "replies": 30, "views": 610396, "ts": 1779617715, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112980026937520608", "url": "https://x.com/itsarcvale/status/2112980026937520608", "text": "YOUR AI BACKTEST IS F*CKING CHEATING. IT TRADES EARNINGS BEFORE THEY WERE EVER PUBLIC\n\na quant builder just laid out how it happens ↓\n> earnings get stamped with the quarter end, not the day they came out. the bot \"predicts\" news it already read\n> the stock list only has companies alive today. every bankruptcy quietly disappears\n> 27 versions tested, only the best one shown\n> $1,200 gross on $10K drops to $600 after 0.2% costs (the piece's own example math)\n\nthe model never calculated any of it. it just sounded sure\n\nnow point it at your own backtest\n\nthe split:\n→ every data point gets the date it went public, not the period it covers\n→ the universe keeps the dead companies\n→ every run gets logged, not just the winner\n→ costs go in before the sharpe, not after\n\nyou only step in three times:\n→ when a curve looks too smooth\n→ when fixing the dates kills the edge. that's the point\n→ before anything goes near real money\n\nthe model writes the idea. the engine does the math. nothing trades on a vibe\n\npaste this into Claude Code ↓\n\n\"Audit my backtest in backtest/:\n1. List every field used for signals and when it became public, not the period it covers. Flag any look-ahead.\n2. Check the universe: does it include delisted and bankrupt tickers on each date? If not, flag survivorship bias.\n3. Shift every signal by one bar and rerun. Show before and after.\n4. Rerun with 0.1% and 0.2% costs per dollar traded.\n5. Log every variant I tried to runs.csv, not just the best one.\nShow me the report first. Don't change any code until I say go.\"\n\none of these every night. tomorrow's goes one layer deeper", "name": "Arcvale", "handle": "itsarcvale", "avatar": "https://pbs.twimg.com/profile_images/2104153950932934656/7lVoY59G_200x200.jpg", "likes": 17, "rts": 2, "replies": 5, "views": 411, "ts": 1792608670, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112979880002334721/vid/avc1/720x900/E-CpxQmK-ocoFzcH.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112979880002334721/vid/avc1/1080x1350/tk6zzK6o1hXjswwo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112979880002334721/img/f1XchoWfzpLCbB-0.jpg", "dur": 18}], "quote": {"id": "2112484949869625543", "url": "https://x.com/0xkvro/status/2112484949869625543", "text": "https://x.com/i/article/2112481525832765440", "name": "kvro", "handle": "0xkvro", "avatar": "https://pbs.twimg.com/profile_images/2048857885225144320/jGg0Jm_U_200x200.jpg", "likes": 58, "rts": 2, "replies": 5, "views": 8975, "ts": 1792490634, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112971680108654748", "url": "https://x.com/adamkp/status/2112971680108654748", "text": "okay, I didn't expect this to work this well\n\n> I gave Codex @maestro__dev MCP and asked it to check whether I'd accidentally broken starred habits while adding the new habit views to @HabitsyApp\n\n> It opened the app on the simulator, tapped through everything, checked the screens, and saved the whole run as a test I can re-run before every release.\n\nbtw, you can now pick from 3 beautiful ways to display your habits in Habitsy", "name": "Adam KP", "handle": "adamkp", "avatar": "https://pbs.twimg.com/profile_images/2097593056023445504/kXAIZk7__200x200.jpg", "likes": 24, "rts": 2, "replies": 2, "views": 1388, "ts": 1792606680, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112507503036579840/vid/avc1/758x720/1ZZXTHtomOcYeWjz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112507503036579840/vid/avc1/1138x1080/M9c8EH4OEjML2a78.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112507503036579840/img/gPamKB1dx82Gwju5.jpg", "dur": 10}], "quote": {"id": "2111187693376098689", "url": "https://x.com/adamkp/status/2111187693376098689", "text": "Another small @HabitsyApp update has been submitted to the App Store:\n\n> Added a new habit card view option: a monthly card that shows all your completions, so you get both the big picture and a clear view of your monthly progress\n\n> Minor polish to the habit detail view\n\n> Further dark mode tweaks (higher contrast on the card background colors)", "name": "Adam KP", "handle": "adamkp", "avatar": "https://pbs.twimg.com/profile_images/2097593056023445504/kXAIZk7__200x200.jpg", "likes": 10, "rts": 1, "replies": 1, "views": 2090, "ts": 1792181344, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111183665401118720/vid/avc1/826x720/cS9aAw1LJ9qNmLcf.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111183665401118720/vid/avc1/1240x1080/moy6MRc50WcX74tQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111183665401118720/img/R2fQh5vR3Tx82mUD.jpg", "dur": 8}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2113044947616362780", "url": "https://x.com/MTSlive/status/2113044947616362780", "text": "Topos Bio CEO Ryan Zarcone explains why designing drugs for Parkinson's and Alzheimer's is almost impossible for humans, but a perfect problem for AI:\n\n\"When a chemist designs a drug for a protein, the model is static. I have this protein, it has a shape, and I’m trying to fill that shape with a drug.\"\n\n\"These really dynamic proteins, like those involved in Parkinson’s and Alzheimer’s, don’t have one shape. They have potentially thousands of different shapes that they’re constantly interconverting between, kind of like someone who’s dancing.\"\n\n\"That becomes basically impossible when you tell a human, design something for these thousand things at the same time. It’s really only been possible to start doing that with AI.\"\n@ToposBio", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 15, "rts": 4, "replies": 0, "views": 3997, "ts": 1792624148, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113044914347106304/vid/avc1/640x360/ymLqGUpuY22ACzAj.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2113044914347106304/vid/avc1/1280x720/1B7nCga2kPtV3s7x.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113044914347106304/img/d9RCzz0nipGLscMQ.jpg", "dur": 102}], "quote": {"id": "2105327604236779807", "url": "https://x.com/ToposBio/status/2105327604236779807", "text": "Today we are announcing Topos-2, our next-generation model for generating the full range of shapes a protein can take, across the order-disorder spectrum.\n\nWe are also previewing Topos-Bind: to our knowledge, the first generative model to capture the range of shapes for disordered proteins bound to small molecules.\n\nRead the technical blog post here: https://www.toposbio.ai/topos-2-topos-bind/\n\n(1/7)", "name": "ToposBio", "handle": "ToposBio", "avatar": "https://pbs.twimg.com/profile_images/2009385890250960896/xG8RY3IX_200x200.jpg", "likes": 347, "rts": 61, "replies": 4, "views": 74501, "ts": 1790784190, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2105325987747827712/vid/avc1/720x720/FTSuA7Y4zaw1cmlz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2105325987747827712/vid/avc1/1080x1080/fHftCCFqDM3UStL1.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2105325987747827712/img/iRlOpbAMTrGUIOdf.jpg", "dur": 27}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112790664761180644", "url": "https://x.com/sidhant/status/2112790664761180644", "text": "\"Domestic political matter, this is a democracy, they have election here, wont opine on there domestic political matter. We have protests in US every day\",says Marco Rubio when asked about India protests\n\nVdo csty: Fox Raw Live now", "name": "Sidhant Sibal", "handle": "sidhant", "avatar": "https://pbs.twimg.com/profile_images/1314827245010132992/jfPBU-7k_200x200.jpg", "likes": 7217, "rts": 798, "replies": 73, "views": 193574, "ts": 1792563522, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112790585048539136/vid/avc1/652x360/pye1lOCQGUM3E1iu.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112790585048539136/vid/avc1/1064x586/DIGGgy9AUnxEQtVF.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112790585048539136/img/ghYK9LHnAbWrsH1X.jpg", "dur": 75}], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112793210808578200", "url": "https://x.com/Abid__Ahasan/status/2112793210808578200", "text": "Claude Code + Blender is changing how 3D creation works.\n\nInstead of manually modeling every component, you can use Python scripts to generate geometry, control animations, and adjust designs through simple parameters.\n\nThe real value isn't just saving time.\n\nIt's making complex 3D workflows reproducible and easier to modify.\n\nBlender remains the creative engine. AI changes how we control it.\n\nThe future isn't about replacing creative skills, but giving creators more power to build.", "name": "Abid.eth", "handle": "Abid__Ahasan", "avatar": "https://pbs.twimg.com/profile_images/2093819163051765760/7tYZ3_dW_200x200.jpg", "likes": 26, "rts": 1, "replies": 15, "views": 639, "ts": 1792564129, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112793186750095360/vid/avc1/846x720/jYODelzUrBUOMjdr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112793186750095360/vid/avc1/1488x1264/Sgc11NHo1E2AYW_Z.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112793186750095360/img/5awEG_6iIyUooE2C.jpg", "dur": 12}], "quote": {"id": "2112734522748055975", "url": "https://x.com/Abid__Ahasan/status/2112734522748055975", "text": "3 AI models, exact same prompt\n\nResult is in front of you 👀", "name": "Abid.eth", "handle": "Abid__Ahasan", "avatar": "https://pbs.twimg.com/profile_images/2093819163051765760/7tYZ3_dW_200x200.jpg", "likes": 27, "rts": 0, "replies": 19, "views": 1297, "ts": 1792550137, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112734487264296960/vid/avc1/640x360/8y1xJIpVRwmPBmZ-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112734487264296960/vid/avc1/1280x720/g4x6bONIYdrihzXh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112734487264296960/img/_wy_YzGd74J0Dooc.jpg", "dur": 11}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.0, "thread": [], "tier": "worth"}, {"id": "2112838997286563971", "url": "https://x.com/imparable55/status/2112838997286563971", "text": "your coding agent helped you ship the product. now imagine letting it handle the creative work too. @avastudio", "name": "Circuit Master", "handle": "imparable55", "avatar": "https://pbs.twimg.com/profile_images/2072030417805266944/2FN9-me3_200x200.jpg", "likes": 23, "rts": 0, "replies": 14, "views": 811, "ts": 1792575046, "media": [], "quote": {"id": "2112606581229769030", "url": "https://x.com/avastudio_/status/2112606581229769030", "text": "We just turned TikToks and Reels into a Claude Code task.\n\nMeet Ava Studio, for founders whose product is live but nobody knows it exists.\n\nGive your agent your product URL and let it research trends across 400,000+ TikToks, write scripts and create videos ready to post.", "name": "Ava Studio", "handle": "avastudio_", "avatar": "https://pbs.twimg.com/profile_images/2060828052645384197/o5Z3NzuU_200x200.jpg", "likes": 760, "rts": 111, "replies": 147, "views": 450724, "ts": 1792519633, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1280x720/wBPNy4C8XvnT1Mr4.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1920x1080/0kVGCjlWFJaXfCpq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606467731943424/img/UhUfy5CUaqFygliU.jpg", "dur": 39}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.0, "thread": [], "tier": "worth"}, {"id": "2112906754681966883", "url": "https://x.com/stepjamUK/status/2112906754681966883", "text": "What if you could test a robot policy without running it on the robot?\n\nPhysCanvas is a world model that predicts what the robot sees and what the fingertips feel, together. Test tube into a rack, unscrewing a bottle cap, bagging blocks, turning a Rubik’s Cube face.\n\nThe number that stood out was adding task-state supervision takes the correlation between world model success and real-world success from 0.60 to 0.89.\n\nThey also ran RL inside the world model on flow matching and π0.5 policies. Real-world performance improved on average, though how much depends on the task.\n\nCode and model are coming soon.\n\nPaper: https://zebinx.github.io/PhysCanvas_HomePage/assets/PhysCanvas.pdf\nProject page: https://zebinx.github.io/PhysCanvas_HomePage/", "name": "Stephen James", "handle": "stepjamUK", "avatar": "https://pbs.twimg.com/profile_images/1981372613491363840/FP7l7yva_200x200.jpg", "likes": 30, "rts": 1, "replies": 4, "views": 1880, "ts": 1792591200, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112882785824186369/vid/avc1/480x360/fUjP_eRPuvy2oklN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112882785824186369/vid/avc1/640x480/UeCELwTdThX3B_7I.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112882785824186369/img/RBnOgvS3mbg5MwGF.jpg", "dur": 44}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.0, "thread": [], "tier": "worth"}, {"id": "2112891662733389953", "url": "https://x.com/realmadrid/status/2112891662733389953", "text": "GOLAZO 🆚 @RBLeipzig\nft. @MarcoAsensio10", "name": "Real Madrid C.F.", "handle": "realmadrid", "avatar": "https://pbs.twimg.com/profile_images/2017009920558731264/G6IgKH-q_200x200.png", "likes": 5871, "rts": 346, "replies": 62, "views": 327247, "ts": 1792587602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112830750542139392/vid/avc1/720x1280/0RN2kKyws8rvwefL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112830750542139392/vid/avc1/1080x1920/Ww1x__2Z4CoQmMrO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112830750542139392/img/rH6HdJOK8wBjMKHq.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.0, "thread": [], "tier": "worth"}, {"id": "2113012152596312107", "url": "https://x.com/CopilotKit/status/2113012152596312107", "text": "OpenEverything", "name": "CopilotKit🪁", "handle": "CopilotKit", "avatar": "https://pbs.twimg.com/profile_images/1961112614785712128/Bnz1cmDG_200x200.jpg", "likes": 17, "rts": 4, "replies": 0, "views": 978, "ts": 1792616329, "media": [], "quote": {"id": "2112572777257402556", "url": "https://x.com/ataiiam/status/2112572777257402556", "text": "We actually already open sourced the big lab AI coworker products👇\n\nOpenBot (6.7k ⭐️) - https://github.com/CopilotKit/OpenBot\nOpenDots (5.7k ⭐️) - https://github.com/CopilotKit/OpenDots\nOpenMuse (5.3k ⭐️)- https://github.com/CopilotKit/openmuse\n\nBots with their own computers. \nWorks with any agent harness.\nTake it to any surface (mobile, web, channels).\nSelf-hostable.\nFully customizable.\n\nMore coming soon from @CopilotKit... 👀", "name": "Atai Barkai", "handle": "ataiiam", "avatar": "https://pbs.twimg.com/profile_images/1649413157893316608/qAX0jKbI_200x200.jpg", "likes": 814, "rts": 93, "replies": 25, "views": 45804, "ts": 1792511574, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFc229WIAAyrl0.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFc23BXcAAlM7h.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFc220XkAEINDy.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.0, "thread": [], "tier": "worth"}, {"id": "2112807511564968098", "url": "https://x.com/daichiandbon/status/2112807511564968098", "text": "モコモコの木ジェネレーター \nmade with C4D MCP", "name": "Daichi Sugimoto🏵️3D Artist", "handle": "daichiandbon", "avatar": "https://pbs.twimg.com/profile_images/1333034144390004739/3Orhe1f4_200x200.jpg", "likes": 50, "rts": 1, "replies": 1, "views": 6073, "ts": 1792567539, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112762954554986496/vid/avc1/540x540/1vwq-c3MR05Syow1.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112762954554986496/vid/avc1/720x720/TOk63q5BN0GR4GHt.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112762954554986496/img/JW97sAczjvrsNy5r.jpg", "dur": 11}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112807450307108865/vid/avc1/640x360/mvHbbtYh3b-gi-JT.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112807450307108865/vid/avc1/1280x720/thXMpYC7KOuMevk1.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112807450307108865/img/1PBIkCnw1XrQNtnl.jpg", "dur": 2}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112861793336840599", "url": "https://x.com/Marlenuii/status/2112861793336840599", "text": "Blender just made Claude Code look f*cking slow\n\nTwo workflows building a complex 3D rocket assembly, and a nearly 19x difference between the timers shown in the demo\n\n213 seconds vs 11 seconds\n\nBut the most interesting part isn’t the speed\n\nIt’s what happens when you stop treating 3D modeling as a manual process and start treating it as programmable engineering\n\nClaude Code can generate Blender Python scripts that control an entire mechanical scene, from geometry and materials to moving parts and cinematic animation\n\nHere’s how to recreate the concept:\n\nOpen Claude Code with Blender installed and paste:\n\n“Build a cinematic rocket assembly using Blender Python\n\nMODEL modular rocket stages, engine nozzles, structural supports, and deployable panels\n\nANIMATE mechanical hinges with adjustable deployment angles and synchronized movement\n\nAPPLY realistic metallic materials, reflections, and studio lighting\n\nCREATE a cinematic camera sequence revealing the internal mechanics\n\nEXPOSE all dimensions, rotation speeds, and animation timings as editable parameters\n\nGenerate one reproducible Python script that builds and animates the entire scene”\n\nNow change the rocket dimensions, deployment sequence, or camera movement without rebuilding everything by hand\n\nThe surprising lesson?\n\nAI doesn’t automatically make every workflow faster\n\nSometimes the biggest advantage is making complex work reproducible, not making the first render finish sooner\n\nBookmark this before your next Blender experiment", "name": "Marlen", "handle": "Marlenuii", "avatar": "https://pbs.twimg.com/profile_images/2106072881423593472/KCZn9bKo_200x200.jpg", "likes": 22, "rts": 2, "replies": 9, "views": 907, "ts": 1792580481, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112860690419519490/vid/avc1/720x900/yxq_d4cmZGc60iZV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112860690419519490/vid/avc1/1080x1350/H2p0oIdS2c7Ht7Fg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112860690419519490/img/w9otWs-gL7PMo69-.jpg", "dur": 25}], "quote": {"id": "2109673372091126158", "url": "https://x.com/Marlenuii/status/2109673372091126158", "text": "https://x.com/i/article/2109671827937120256", "name": "Marlen", "handle": "Marlenuii", "avatar": "https://pbs.twimg.com/profile_images/2106072881423593472/KCZn9bKo_200x200.jpg", "likes": 44, "rts": 2, "replies": 1, "views": 75133, "ts": 1791820302, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112943242300002431", "url": "https://x.com/premierleague/status/2112943242300002431", "text": "A hat-trick in only his second Premier League match 😅\n\nJust Teemu Pukki things 👀", "name": "Premier League", "handle": "premierleague", "avatar": "https://pbs.twimg.com/profile_images/1742837199005954048/YGI6Kw7P_200x200.jpg", "likes": 5031, "rts": 242, "replies": 54, "views": 285981, "ts": 1792599900, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112934824239345664/vid/avc1/720x1280/smt0-AQLQUXAnNHr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112934824239345664/vid/avc1/1080x1920/_pcw6nawgqBIjasR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112934824239345664/img/uRNvcdl-lTgWetGh.jpg", "dur": 33}], "quote": null, "reply_to": null, "cat": "Sports", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112859917329547770", "url": "https://x.com/xinc3s/status/2112859917329547770", "text": "NOBODY TALKS ABOUT THESE 12 💀\n\n12 Claude Code commands sitting in the menu that almost nobody types. the last one quietly took a job off my plate.\n\n→ /subtask: a forked agent takes a side task, you keep working, the result comes back to you\n→ /background: detach the session, free the terminal, it keeps going\n→ /teleport: pull a cloud session into your terminal, branch and chat included\n→ /context: see what's eating your context window as a colored grid\n→ /diff: every edit Claude made, before you trust any of it\n→ /verify: it runs your app to check the change works, not just the tests\n→ /security-review: scans your branch for injection, auth and data leaks\n→ /ultrareview: a multi-agent code review in a cloud sandbox\n→ /fewer-permission-prompts: reads your history, allowlists the safe stuff\n→ /insights: a report on how you use Claude Code and where it goes wrong\n→ /recap: one line on what this session actually did\n\nand the one that changed everything:\n\n/autofix-pr.\n\nit watches your PR. CI fails or a reviewer leaves a comment, it pushes the fix. you find out when it's green.\n\n(not hidden. it's all in the docs. nobody scrolls past /help.)\n\nbookmark this. you'll want it the next time CI goes red at 2am.", "name": "xinces", "handle": "xinc3s", "avatar": "https://pbs.twimg.com/profile_images/2105649446595809280/hrPBOnoq_200x200.png", "likes": 23, "rts": 4, "replies": 6, "views": 719, "ts": 1792580033, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112859737435865088/vid/avc1/720x960/8tn-WbcrlzR2bH_i.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112859737435865088/vid/avc1/1080x1440/mVeXGnxy49rRuH3i.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112859737435865088/img/KOGDCinhONwoq0S_.jpg", "dur": 26}], "quote": {"id": "2108204467774509059", "url": "https://x.com/xinc3s/status/2108204467774509059", "text": "https://x.com/i/article/2108190000156176384", "name": "xinces", "handle": "xinc3s", "avatar": "https://pbs.twimg.com/profile_images/2105649446595809280/hrPBOnoq_200x200.png", "likes": 36, "rts": 4, "replies": 2, "views": 22239, "ts": 1791470088, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2113119946599272680", "url": "https://x.com/MrTacticalX/status/2113119946599272680", "text": "Claude Opus 5.5 vs Claude Fable 5.1: “WWII mountain fortress in a blizzard.”🏔️\n\nBuilt entirely in Blender with Python. Cable car, train, searchlights, flak guns, northern lights. No assets.\n\nFable 5.1 (Extra High): 104 min, ~$50.26\nOpus 5.5 (Extra High): 150 min, ~$38.07\n\nOpus 5.5 > Fable 5.1", "name": "Mr Tactical", "handle": "MrTacticalX", "avatar": "https://pbs.twimg.com/profile_images/2109983814856396800/te17eghr_200x200.jpg", "likes": 14, "rts": 0, "replies": 3, "views": 1550, "ts": 1792642029, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113119279017062400/vid/avc1/1280x720/dHfzJL3bRDHk3otI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113119279017062400/vid/avc1/1920x1080/qR-j3VVbLhINPiFk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113119279017062400/img/-683LhLa2VNqxwV2.jpg", "dur": 46}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112904991119687802", "url": "https://x.com/magsimich/status/2112904991119687802", "text": "Holy F*ck why is no one doing it? \n\nPeople are making money by making cool cycling video with ai \n\nThis video has generated over 55m views and $1,500 in revenue \n\nAnd the best part is it took less then 5 min to create \n\nYou can see the video a POV short where the sky is orange and the road is getting down and the view is very cool which makes people to watch it and feel it \n\nWhen you watch it you also feel like you wanna go there but for your information this place is not exist it's ai generated which made \n\n- 55m views \n- $1,500 from brand deals\n- 14.3k followers \n\nTime? It took less then 5 min to create let me tell you how you can do it \n\n-> first screenshot the video \n-> ask any chatbot to replace the background you can ask him to find better place and let him generate the image first \n\n-> after getting that image use any video model upload that image and enter this prompt: animate it \n\n-> done you'll have now your own ai generate cycling road video now generate more videos keep posting when you get viral you could easily get 1~3 brand deals \n\nJust need to be consistent and that's all", "name": "magsimich", "handle": "magsimich", "avatar": "https://pbs.twimg.com/profile_images/2067590814855737344/UsDKYROw_200x200.jpg", "likes": 23, "rts": 1, "replies": 7, "views": 897, "ts": 1792590780, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112888500806922240/vid/avc1/480x852/JXIgh5my88KQlL_A.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112888500806922240/vid/avc1/720x1280/yEuFRE_l4MR5LFz0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112888500806922240/img/iLS4_e9ibc5zYhd8.jpg", "dur": 13}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112975823095628272", "url": "https://x.com/LangChain/status/2112975823095628272", "text": "On October 28th, go behind the scenes of our design agent.\n\nWe’ll demo the agent live, walk through how we built it, and share what we’ve learned from using an agent for creative production across the company.\n\n💻 RSVP: https://events.langchain.com/gtm-engineering-live-series/design-agent/", "name": "LangChain", "handle": "LangChain", "avatar": "https://pbs.twimg.com/profile_images/2028336270431453184/jRRpLAdG_200x200.jpg", "likes": 19, "rts": 3, "replies": 2, "views": 4975, "ts": 1792607668, "media": [], "quote": {"id": "2112975342264868978", "url": "https://x.com/amal_irgashev/status/2112975342264868978", "text": "our design agent at @LangChain has shipped 3,000+ assets since august, and posts with its work pulled ~4.5M views on socials (it made this promo too)\n\nit’s become the design brain for the whole org. decks, diagrams, ad creatives, launch films and more, all made from slack\n\nwe encoded our designers’ judgment into its skills, a design wiki and brand checks that run on every render, so it knows what good looks like for us\n\nthen we built a custom media harness around it: a headless photoshop, a shared visual canvas (thanks @paper), video tools like @HyperFrames_ plus our own animation engine, our brand assets and a library of design references\n\nit runs on Managed Deep Agents, which abstracts away a ton of infra including sandboxes, agent memory, slack integration, scheduling and more.\n\nwe are going through the architecture, use cases and impact live at our oct 28 webinar 👇\n\nhttp://events.langchain.com/gtm-engineering-live-series/design-agent/", "name": "Amal Irgashev", "handle": "amal_irgashev", "avatar": "https://pbs.twimg.com/profile_images/2091745918957883392/x6ikN8rR_200x200.jpg", "likes": 22, "rts": 5, "replies": 4, "views": 8794, "ts": 1792607553, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112959564509552640/vid/avc1/720x720/8v6Fct-c2mIKVQp9.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112959564509552640/vid/avc1/2160x2160/vskMMjlKZZtd1a1n.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112959564509552640/img/p5yYn43P6Rpcfqe2.jpg", "dur": 34}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.99, "thread": [], "tier": "worth"}, {"id": "2112881493575917921", "url": "https://x.com/hammertime_one/status/2112881493575917921", "text": "SpaceXAI's Grok Bot team put 10 of its own bot templates in the marketplace, and this is a f*c*ing goldmine\n\nyou don't write a system prompt from scratch, you import a setup built for one job, connect your tools, and adapt it\n\nthe 10:\n\n1. dr eggbot builds other Grok Bots. Describe the job, it helps you build the specialist.\n\n2. Engineer Bot (Lingxi) supervises cloud coding agents and watches their PRs. You handle the merge.\n\n3. Stalk Bot watches competitors: product, pricing and positioning changes, with sources.\n\n4. Haggle Bot finds wasted SaaS spend and drafts vendor negotiations for your review.\n\n5. Proto Bot turns feature ideas into prototypes inside your app, as draft PRs.\n\n6. Video Editor picks takes from raw footage and builds captioned vertical videos. You approve the edit plan first.\n\n7. figma bro turns Figma frames into build specs and checks your components and design tokens.\n\n8. Distro Bot runs marketing campaigns and creative. Approval before spending, posting or sending.\n\n9. Startup QA Bot walks through your product in a test account and reports bugs with screenshots and steps.\n\n10. Signal Prospector finds buying signals in your CRM and product data, then drafts outreach around the evidence.\n\nlook at what they share\n\none job per bot, and 6 of the 10 stop at a human: a merge, a review, a draft PR, an approved plan\n\nthat is the same rule the 7 Grok Bot guides I read agree on\n\npick the one closest to your work, import it tonight\n\nthat is one evening you don't spend on a system prompt", "name": "hammertime", "handle": "hammertime_one", "avatar": "https://pbs.twimg.com/profile_images/2105980393258135552/MN4JaKHX_200x200.jpg", "likes": 27, "rts": 0, "replies": 8, "views": 621, "ts": 1792585178, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112865688519880704/vid/avc1/720x900/DfouxIYCivVrVtyD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112865688519880704/vid/avc1/2160x2700/unYkMuTwQxNB-qze.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112865688519880704/img/-D-4Cvd0Lb-VSZBO.jpg", "dur": 38}], "quote": {"id": "2093607787817267607", "url": "https://x.com/Mikadzyki_NFT/status/2093607787817267607", "text": "https://x.com/i/article/2093596027815141376", "name": "Mikadzyki🌙", "handle": "Mikadzyki_NFT", "avatar": "https://pbs.twimg.com/profile_images/2094301804611633152/1H8uVIE__200x200.jpg", "likes": 132, "rts": 18, "replies": 36, "views": 285051, "ts": 1787989968, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.98, "thread": [], "tier": "worth"}, {"id": "2112781120316043599", "url": "https://x.com/fabulous__xx/status/2112781120316043599", "text": "building got easy. marketing didn’t. this closes the gap. @avastudio_", "name": "Fabulous💸", "handle": "fabulous__xx", "avatar": "https://pbs.twimg.com/profile_images/2105024419458351105/VLAIXRhT_200x200.jpg", "likes": 21, "rts": 5, "replies": 11, "views": 444, "ts": 1792561247, "media": [], "quote": {"id": "2112606581229769030", "url": "https://x.com/avastudio_/status/2112606581229769030", "text": "We just turned TikToks and Reels into a Claude Code task.\n\nMeet Ava Studio, for founders whose product is live but nobody knows it exists.\n\nGive your agent your product URL and let it research trends across 400,000+ TikToks, write scripts and create videos ready to post.", "name": "Ava Studio", "handle": "avastudio_", "avatar": "https://pbs.twimg.com/profile_images/2060828052645384197/o5Z3NzuU_200x200.jpg", "likes": 760, "rts": 111, "replies": 147, "views": 450693, "ts": 1792519633, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1280x720/wBPNy4C8XvnT1Mr4.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1920x1080/0kVGCjlWFJaXfCpq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606467731943424/img/UhUfy5CUaqFygliU.jpg", "dur": 39}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2112843605048184890", "url": "https://x.com/RykerStone123__/status/2112843605048184890", "text": "OpenAI CEO, Sam Altman: The \"AI is wasting our water\" story doesn't survive the math.\n\n\"For every 38,000 ChatGPT queries, that is the same amount of water that is used in the production of a single almond in California.\"\n\n\"This is the full-on, total true water accounting, not just what's running in one data center.\"\n\n\"It is true that data centers at one point used evaporative cooling. But they have not done that in a long time.\"\n\n\"A modern, very large data center uses the equivalent amount of water as an office building.\"\n\n\"That has been a robust meme and difficult to disprove, but I don't think it holds up to any scrutiny.\"\n\nis he right?", "name": "Ryker Stone", "handle": "RykerStone123__", "avatar": "https://pbs.twimg.com/profile_images/2076569558211870720/i6m3QMuY_200x200.jpg", "likes": 12, "rts": 9, "replies": 4, "views": 659, "ts": 1792576144, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112843558172733440/vid/avc1/1280x720/uTqR3pmN1eiSygaj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112843558172733440/vid/avc1/1920x1080/84Z_ZJEaRszE125U.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112843558172733440/img/0z4Qnq4Sl3jSHJ64.jpg", "dur": 55}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2112857498558574667", "url": "https://x.com/goon_nguyen/status/2112857498558574667", "text": "i just made this anime clip! 😁\n\nAI video folks be like: “bro, you just prompted Seedance, big deal” 😂\n\nplot twist: i made it with Opus 5.5!\n\nyes, seriously!\n\nSeedance is amazing, but a 15-second clip can cost $4-5, and every regeneration burns more money.\n\nso i tried something different...\n\nOpus 5.5 orchestrated Codex to generate images, remove backgrounds, separate layers, and composite everything in HyperFrames, using Three.js and shaders for depth of field, camera movements, and particle effects.\n\ntotal cost? ~$3. \n\nincluding music, voice, and sound effects (excluding Claude subscription tokens 😁)\n\nthe best part? everything is editable, just like After Effects.\n\nno need to regenerate an entire video just to fix one tiny detail.\n\nand watching how Opus 5.5 reasoned through this workflow was fascinating.\n\nwhat if the future of AI filmmaking isn’t generating videos, but AI learning to use filmmaking tools?", "name": "Duy /zuey/", "handle": "goon_nguyen", "avatar": "https://pbs.twimg.com/profile_images/1987675020106346496/Vb_EQtRX_200x200.jpg", "likes": 17, "rts": 0, "replies": 14, "views": 1196, "ts": 1792579457, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112857457970360320/vid/avc1/1280x720/Dl_lhMH0PiORu_C-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112857457970360320/vid/avc1/1920x1080/oMitYOJsRUmhPk6q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112857457970360320/img/Rb9jvcEBlKcs1ePk.jpg", "dur": 17}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2112781775034581050", "url": "https://x.com/chongdashu/status/2112781775034581050", "text": "I just made Retro del Sol - a beautiful, low-poly pixel art world.\n\nPowered by Retro Diffusion for the art assets \n(yes, it does 3D & is amazing!)\n\nHighlights:\n→ Fully persistent MULTIPLAYER world \n→ Day-night cycles\n→ Vehicles\n→ Character customisation\n\nYou can deliver parcels to earn money or simply travel around the different islands.\n\nPlay it: https://retrodelsol.com \n\nWorks right in your browser and on mobile.", "name": "Chong-U", "handle": "chongdashu", "avatar": "https://pbs.twimg.com/profile_images/2109521104167661568/eKr4dw03_200x200.jpg", "likes": 31, "rts": 3, "replies": 9, "views": 3324, "ts": 1792561403, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112781330060840960/vid/avc1/1280x720/0x8i5osDdPVbq23n.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112781330060840960/vid/avc1/1920x1080/kCFzrhi9mwR0ytKF.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112781330060840960/img/PHfcGun_CBueJ7Ol.jpg", "dur": 62}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2112946217009471683", "url": "https://x.com/elder_plinius/status/2112946217009471683", "text": "https://blackhat.com/europe/briefings/schedule/#kinetic-prompt-injection-agent-compromise-with-a-physical-blast-radius-57895", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 28, "rts": 0, "replies": 3, "views": 3486, "ts": 1792600609, "media": [], "quote": null, "reply_to": "2112946187670315329", "cat": "AI Tools & Agents", "score": 4.97, "thread": [{"id": "2112946187670315329", "url": "https://x.com/elder_plinius/status/2112946187670315329", "text": "we'll be jailbreaking a Unitree onstage at Black Hat EU! 🤖⛓️‍💥\n\nhope to see y'all there 🤗", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 639, "rts": 34, "replies": 39, "views": 21638, "ts": 1792600602, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKwWXBbEAAB0mO.jpg?name=orig"}], "quote": null, "reply_to": null}], "tier": "skim"}, {"id": "2112977646376091997", "url": "https://x.com/reMugi3/status/2112977646376091997", "text": "A DESIGNER SOLD FOUR $2,400 LANDING PAGES. GROK BOT DID THE NIGHT SHIFT\n\nhe dropped the briefs into Grok Bot. one specialist built, another checked mobile layouts, and a third tested every form before the work reached him\n\nat second 12, a broken form stops the launch. the page goes back for a fix instead of landing in the client's inbox\n\nfour approved sites. $9,600 gross. he still handled the clients and final sign-off\n\npeople billing two weeks for this should probably watch\n\nbookmark the workflow below.", "name": "Mugi", "handle": "reMugi3", "avatar": "https://pbs.twimg.com/profile_images/2007777985542164480/c6XhmbrQ_200x200.jpg", "likes": 24, "rts": 0, "replies": 3, "views": 409, "ts": 1792608102, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112976639227293696/vid/avc1/720x900/YWjAu22NPXUpTPx6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112976639227293696/vid/avc1/1080x1350/eFey68oue4oTJ0rc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112976639227293696/img/RCdzBvbDYsYDzWNf.jpg", "dur": 24}], "quote": {"id": "2112229483956634111", "url": "https://x.com/crangerus/status/2112229483956634111", "text": "Elon Musk's Grok Bot has a cloud computer. What should you actually make it do?\n\nHere are 15 prompts for code, research, and writing. Copy one, give your bot a job, and check what comes back. https://x.com/i/article/2112164553328918528", "name": "cranger", "handle": "crangerus", "avatar": "https://pbs.twimg.com/profile_images/2001803069219074048/25cyNj3G_200x200.jpg", "likes": 27, "rts": 4, "replies": 1, "views": 30292, "ts": 1792429726, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2113047270694220130", "url": "https://x.com/FoxNews/status/2113047270694220130", "text": "David Spade is pushing back against the outrage surrounding Shane Gillis' controversial \"SNL\" monologue, telling critics to \"relax\" after the comedian sparked backlash for mocking women's gym attire.\n\nSpade and fellow \"SNL\" alum Dana Carvey are defending the right to tell jokes that push boundaries, even when audiences don't find them funny.\n\nSpade also takes aim at what he sees as a glaring Hollywood double standard: https://www.foxnews.com/entertainment/david-spade-tells-critics-relax-shane-gillis-faces-backlash-snl-joke", "name": "Fox News", "handle": "FoxNews", "avatar": "https://pbs.twimg.com/profile_images/2109614018314862592/Pc5TwaVr_200x200.jpg", "likes": 3165, "rts": 181, "replies": 131, "views": 348762, "ts": 1792624702, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVMNS5KWsAAIJYc.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.97, "thread": [], "tier": "skim"}, {"id": "2112845545920491768", "url": "https://x.com/sideshiftai/status/2112845545920491768", "text": "Weekly Report: 13th - 19th October 2026\n\n∙ $7.47m volume (-16.7%), 8,652 shifts\n∙ USDT (Liquid)/BTC record: $902k, ~5x any other pair\n∙ +$1.15m net stablecoin inflow for 6 weeks running\n∙ Alt networks took 69.4% vs Ethereum, Solana at #1\n\nRead report: https://sideshift.ai/research/weekly-report-13th-19th-october-2026", "name": "SideShift.ai - Direct to Wallet Trading", "handle": "sideshiftai", "avatar": "https://pbs.twimg.com/profile_images/1889626541933600769/9kuet0T0_200x200.png", "likes": 19, "rts": 3, "replies": 9, "views": 642, "ts": 1792576607, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112845308124422144/vid/avc1/1280x720/tqUhYtruad_IZW-j.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112845308124422144/vid/avc1/1920x1080/JSAlpZ63s9leTa-G.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112845308124422144/img/EixX0SoUp54z9Lpu.jpg", "dur": 5}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 4.96, "thread": [], "tier": "skim"}, {"id": "2112896686486130965", "url": "https://x.com/MarioNawfal/status/2112896686486130965", "text": "🇮🇳 Your BANK, your email, practically ANY website could have been impersonated, with your browser none the wiser. \n\nAll thanks to one company's INSANE security blunder.\n\nIndian company eMudhra, trusted to certify that websites are genuine, used EIGHT cryptographic keys so ridiculously weak they could be cracked almost instantly.\n\nHow weak? A normal key relies on a secret number roughly 116 digits long. \n\neMudhra's secret numbers? Just 4, 56 and 237. These are NOT pieces of the keys. They were the ACTUAL numbers! 🤯\n\nAnyone with those keys could have forged trusted certificates for virtually any website, potentially fooling your browser if they intercepted your connection.\n\nMajor browsers have already blocked the keys, and there's no confirmed malicious use so far.\n\nBut cleaning up older devices and software could be a nightmare. An expert warns it could be bigger than Heartbleed, the infamous 2014 security disaster that took years to fix, because millions of old devices and systems still need updating.\n\nAnd here we are, being told our passwords need another capital letter and a special character.\n\nSource: Ars Technica / Writer: Julie", "name": "Mario Nawfal", "handle": "MarioNawfal", "avatar": "https://pbs.twimg.com/profile_images/1938244629071015936/UwtzYY-R_200x200.jpg", "likes": 3705, "rts": 765, "replies": 126, "views": 393144, "ts": 1792588800, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJvhlCW0AARBgL.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.96, "thread": [], "tier": "skim"}, {"id": "2112975404323770452", "url": "https://x.com/0xV0LYX/status/2112975404323770452", "text": "TESLA OPTIMUS GOT PROMOTED TO BOSS IN 24 HOURS. THE MANAGER’S LAST WORDS WERE “YOU’LL NEVER REPLACE ME”\n\nTesla Optimus got promoted to boss by 9:02 the next morning. It’s not a robot takeover. It’s a performance review.\n\nThe scene is office CCTV, fisheye, timestamp ticking. Monday, 09:14: a robot types at superhuman speed beside a neat stack of finished reports. A manager storms in, slams papers on its desk and shouts “You’ll never replace me!” The robot stands up, slowly, to its full height. The manager steps back.\n\nTuesday, 09:02: the robot sits in the glass corner office in the leather chair, legs crossed, coffee in hand, the manager’s tie around its neck. The manager walks past with a box: a plant, a framed photo, a stapler. The robot gives a polite wave.\n\nHonest catch: this is an AI-generated video concept built from a written prompt, not real CCTV footage. Nothing like this happened.\n\nExpert take: Gartner forecast in 2024 that one in five organizations would use AI to flatten structures and cut more than half of middle management roles. Manager headcount at US public companies already fell 6.1% between May 2022 and May 2025, per CNBC. But the boss replacing you in 2036 isn’t a humanoid. It’s software that schedules, tracks and reports. The humans who survive coach people.\n\nWould you rather report to a robot that never forgets your output, or a human who does?", "name": "V0LYX", "handle": "0xV0LYX", "avatar": "https://pbs.twimg.com/profile_images/1889041459145256960/v6yp8Cbp_200x200.jpg", "likes": 22, "rts": 0, "replies": 4, "views": 638, "ts": 1792607568, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112975353715052544/vid/avc1/720x1080/F34VKXiS9IQIHO1L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112975353715052544/vid/avc1/1080x1620/kRAWQNr0nvUJCFTH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112975353715052544/img/CBaPDrYX1pIWYA57.jpg", "dur": 10}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.96, "thread": [], "tier": "skim"}, {"id": "2112986503609475456", "url": "https://x.com/bubbubbdex/status/2112986503609475456", "text": "I SET UP GROK BOT THIS MORNING. IT FOUND AN OLD ACCOUNT THAT COULD READ OUR BRAND-NEW KEYS\n\nAfter the PHP alert, I gave the new Bot team an isolated mirror of our infrastructure to test CVE-2026-109618 and CVE-2026-109619.\n\nIt recovered archive-sync from a live worker and pulled the account's shutdown ticket. November 2025. We'd marked it retired eleven months ago. Today's worker was still loading its credential.\n\nThen Grok Bot followed the backup jobs.\n\nEvery production-secret rotation sent a fresh configuration snapshot into our archive. archive-sync still had read access to the entire thing. The keys we'd replaced this morning were already in reach.\n\nThe Bot joined today's worker state with the old permission records and backup manifests:\n\n17 forgotten identities → 6 still enabled → 1 connector reaching every new backup.\n\nChief packaged the evidence and stopped before opening an archive file. I had to approve the next step.\n\nI checked the signature on that November shutdown ticket. Mine.\n\nWe disabled the connector and rotated the exposed secrets again. This time, I checked where the copies went.\n\nThe Bot's first security job had uncovered eleven months of us delivering fresh keys back into an old account's reach.", "name": "bubbdex", "handle": "bubbubbdex", "avatar": "https://pbs.twimg.com/profile_images/2093479609903849472/xK0RLDaz_200x200.jpg", "likes": 16, "rts": 3, "replies": 2, "views": 682, "ts": 1792610214, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112983400512425984/vid/avc1/720x900/coSvkaLuKcKPu_se.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112983400512425984/vid/avc1/1080x1350/S1Gr3LA0YnVC2uxT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112983400512425984/img/FpmKpxAyYLMWR-lE.jpg", "dur": 24}], "quote": {"id": "2112756056678134169", "url": "https://x.com/cyber_forecast/status/2112756056678134169", "text": "PHPのセキュリティチームが、重大な２件の脆弱性に関する注意喚起を行っています。公開しているウェブサイトでPHPを使用しているか確認し、10月21日午後11時（日本時間）に公開される修正パッチについて、可及的速やかに適用できるよう準備をお願いいたします。\nhttps://www.php.net/archive/2026.php#2026-10-20-1", "name": "国家サイバー統括室(注意・警戒情報)", "handle": "cyber_forecast", "avatar": "https://pbs.twimg.com/profile_images/1939846741299482624/mhOaP-wP_200x200.png", "likes": 134486, "rts": 60282, "replies": 432, "views": 61005579, "ts": 1792555271, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.96, "thread": [], "tier": "skim"}, {"id": "2112794766744432674", "url": "https://x.com/IFM_AI/status/2112794766744432674", "text": "Jais-ASR ranks #1 on the Open Universal Arabic ASR Leaderboard.\n\nOur open model is built for Modern Standard Arabic and dialects from 19 countries.\n\nBeyond the leaderboard, it handles:\n- Natural code-switching with English, French, Spanish, and Italian\n- Robustness to background noise\n- Faithful transcription, resistant to hallucinations\n- Arabic diacritization\n- Built-in language and dialect identification\n\nWeights released under Apache 2.0: https://huggingface.co/IFM/Jais-ASR", "name": "Institute of Foundation Models", "handle": "IFM_AI", "avatar": "https://pbs.twimg.com/profile_images/2044080954491424769/sUZGe9SC_200x200.png", "likes": 22, "rts": 7, "replies": 5, "views": 856, "ts": 1792564500, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVInoOmbQAADff3.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2112867372860113012", "url": "https://x.com/xiax0603/status/2112867372860113012", "text": "🚨重磅！Kimi K3.1信号实锤，真的离发布不远了！\n\n代码配置文件曝光映射规则，原有k3、kimi-k3、kimi-for-coding等多个模型入口，已经定向路由到k3.1。\n\n平台新增会话切换提示，中途切至Kimi K3.1会弹出质量变更提醒，侧面印证版本已经接入系统后台，正在Kimi Code环境中做上线前验证。\n\n目前官方尚未官宣确切发布时间，但从后台配置进度来看，新版本马上就要推出。", "name": "xiax｜AI & Agents", "handle": "xiax0603", "avatar": "https://pbs.twimg.com/profile_images/2106557854895509504/5MNfNPOr_200x200.jpg", "likes": 21, "rts": 0, "replies": 10, "views": 5750, "ts": 1792581811, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJpqWKagAIYEHF.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVJprEDa0AE6mlM.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2112911095115710748", "url": "https://x.com/TimJayas/status/2112911095115710748", "text": "if gemini 4 flash could beat deepseek-v4.1-flash-1017 in both pricing and performance only then i’ll consider this to be google’s real comeback, not carbon", "name": "Tim Jayas", "handle": "TimJayas", "avatar": "https://pbs.twimg.com/profile_images/2016190209768226821/MW5mAfL-_200x200.jpg", "likes": 27, "rts": 1, "replies": 3, "views": 1686, "ts": 1792592235, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2112954342122648042", "url": "https://x.com/JasonKuperberg/status/2112954342122648042", "text": "I caught @Garmin’s new Personal API mid-rollout.\n\nSo I tested every endpoint and built this from my own data... every run, climb, night of sleep, and HRV reading from my summer ⬇️", "name": "Jason Kuperberg", "handle": "JasonKuperberg", "avatar": "https://pbs.twimg.com/profile_images/1767740783413624832/xiTn_rIV_200x200.jpg", "likes": 10, "rts": 3, "replies": 6, "views": 6698, "ts": 1792602546, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK4wrTWwAAqu1t.png?name=orig"}], "quote": {"id": "2112921616770588988", "url": "https://x.com/JasonKuperberg/status/2112921616770588988", "text": "hey @Garmin, is the personal API key feature supposed to be live?\n\ni got a real token issued but the info pages are all placeholders and my key doesn't appear to be working yet.\n\nwould love to help test if there's a new Garmin API launching soon!\n\nhttps://connect.garmin.com/app/settings/personalApiToken", "name": "Jason Kuperberg", "handle": "JasonKuperberg", "avatar": "https://pbs.twimg.com/profile_images/1767740783413624832/xiTn_rIV_200x200.jpg", "likes": 2, "rts": 0, "replies": 0, "views": 6918, "ts": 1792594744, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKZsDkWMAAjpi1.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVKa3wwXcAAxm5u.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2112880154296926550", "url": "https://x.com/SteticIA/status/2112880154296926550", "text": "Claude Code en realidad tiene una “App Store” para agentes 🤯\n\nLas Plantillas de Claude Code te dan más de 1,000 componentes listos para usar y mejorar tu configuración.\n\n- Agentes especializados\n- Habilidades y comandos reutilizables\n- Integraciones MCP\n- Ganchos y configuraciones de proyecto\n\nElige lo que necesites, copia el comando de instalación y ponlo a trabajar.\n\nCódigo abierto. Gratis para instalar.", "name": "Stefan Friedman", "handle": "SteticIA", "avatar": "https://pbs.twimg.com/profile_images/2074578940090335232/xgwxQsrZ_200x200.jpg", "likes": 32, "rts": 0, "replies": 4, "views": 1375, "ts": 1792584858, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112879960813629440/vid/avc1/1146x720/8ZoJn5DPXu9AboKu.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112879960813629440/vid/avc1/3442x2160/oPFPi0T88wBXizO_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112879960813629440/img/I7t361iilwXWKtjF.jpg", "dur": 11}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2113014090956148753", "url": "https://x.com/ABC/status/2113014090956148753", "text": "Animal rescuers in Utah used a remote-controlled crawler nicknamed \"R2-D2\" to gently nudge a trapped kitten out of a drain pipe. https://abcnews.link/JMzoZh7", "name": "ABC News", "handle": "ABC", "avatar": "https://pbs.twimg.com/profile_images/1605211963096801282/3flU1i5o_200x200.jpg", "likes": 3151, "rts": 328, "replies": 50, "views": 328504, "ts": 1792616791, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2113014048463663104/pu/vid/avc1/480x852/_IiiEXLt65AvPBTk.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2113014048463663104/pu/vid/avc1/720x1280/8gJSvM96xnatpt-f.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2113014048463663104/pu/img/geAL-fHZXG8KMINw.jpg", "dur": 26}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.95, "thread": [], "tier": "skim"}, {"id": "2112779342166069330", "url": "https://x.com/CallmeSpazee/status/2112779342166069330", "text": "marketing teams have had this workflow for years. \n\nbut with @avastudio_ now solo builders are getting their own version of it.", "name": "Spazze 🈳", "handle": "CallmeSpazee", "avatar": "https://pbs.twimg.com/profile_images/2023472374038077440/p9PxRjHg_200x200.jpg", "likes": 17, "rts": 7, "replies": 8, "views": 393, "ts": 1792560823, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1280x720/wBPNy4C8XvnT1Mr4.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1920x1080/0kVGCjlWFJaXfCpq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606467731943424/img/UhUfy5CUaqFygliU.jpg", "dur": 39}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.94, "thread": [], "tier": "skim"}, {"id": "2112939974685515941", "url": "https://x.com/RapSheet/status/2112939974685515941", "text": "NFL Commissioner Roger Goodell says, “We welcome it” with regards to the NFLPA asking for an investigation on Jalen Hurts’ medical situation.", "name": "Ian Rapoport", "handle": "RapSheet", "avatar": "https://pbs.twimg.com/profile_images/1032279765862965248/MaAIgBaS_200x200.jpg", "likes": 4539, "rts": 150, "replies": 126, "views": 710861, "ts": 1792599121, "media": [], "quote": null, "reply_to": null, "cat": "Sports", "score": 4.94, "thread": [], "tier": "skim"}, {"id": "2113028586538205563", "url": "https://x.com/Classic_crypt/status/2113028586538205563", "text": "Some people would rather postpone booking an appointment than deal with endless hold music at the doctor's office. Being able to text someone to manage bookings and follow-ups would make healthcare so much easier", "name": "Classic", "handle": "Classic_crypt", "avatar": "https://pbs.twimg.com/profile_images/2100726410142789632/92CnHqHz_200x200.jpg", "likes": 17, "rts": 1, "replies": 2, "views": 1075, "ts": 1792620247, "media": [], "quote": {"id": "2112937489497534685", "url": "https://x.com/sujaldkl/status/2112937489497534685", "text": "Today, I'm launching Vene: your AI advocate for healthcare.\n\nI used to spend a dozen hours a week managing care for my dad, a disabled veteran, and my mom, who has a severe autoimmune disease. Healthcare was a full-time job for my family.\n\nOur goal is to end the burden of care for every family:\n\nWhen you're sick, or caring for someone who is, the hard part is everything after the hospital: the referral that never arrives, the test result nobody calls about, the bill that makes no sense, and everything in between.\n\nFor my dad, he spent hours on the phone to book an MRI. When he showed up, they told him to his face that insurance had stopped covering it. Then insurance told him to call a list of other offices and get the paperwork sent over himself, and he ended up giving up.\n\nThat’s why we’ve trained Vene to handle the toughest aspects of healthcare:\n- Coordinating several specialists at once\n- Challenging surprise bills and treatment denials\n- Catching missed follow-ups and care gaps\n\nMy mom uses Vene to coordinate her primary care and endocrinologist, automatically refill and renew her prescriptions, and manage my little sister’s dental appointments.\n\nThey were my first users, and now over 5,000 families use Vene, and we're deploying it to another 50,000 patients across provider networks in the US.", "name": "sujal", "handle": "sujaldkl", "avatar": "https://pbs.twimg.com/profile_images/1994690767055355904/RsBcmRV__200x200.jpg", "likes": 711, "rts": 133, "replies": 229, "views": 185771, "ts": 1792598528, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112937266503196672/vid/avc1/1044x720/ZNzBJ-dn5L_lNmkg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112937266503196672/vid/avc1/1566x1080/9lpxyB2wNa6FI7QS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112937266503196672/img/uftLmYn6oGwI8YWf.jpg", "dur": 93}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.94, "thread": [], "tier": "skim"}, {"id": "2112794341823701456", "url": "https://x.com/TimJayas/status/2112794341823701456", "text": "all of a sudden google started shipping s-tier models instead of flash model every month\n\nits only been a week since we got gemini 4 argon and now we're already expected to get gemini 4 carbon in coming weeks with partners already having early access for testing", "name": "Tim Jayas", "handle": "TimJayas", "avatar": "https://pbs.twimg.com/profile_images/2016190209768226821/MW5mAfL-_200x200.jpg", "likes": 36, "rts": 2, "replies": 4, "views": 2078, "ts": 1792564399, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.93, "thread": [], "tier": "skim"}, {"id": "2112914510721830986", "url": "https://x.com/reinexbt/status/2112914510721830986", "text": "This is f*cking insane. Google CEO Sundar Pichai:\n\n\"If you don't learn to orchestrate agents now, you'll spend 2027 catching up to people who started today\"\n\nIn 30 minutes, he explains why top engineers are moving from writing code to building harnesses that coordinate agents\n\nResearch Node → Writing Node → Test Node → Review Node → Fix Node\n\nThe harness routes the work and checks each handoff\n\nThe human becomes the operator, not the bottleneck\n\nAgents → Harness → Verification → Feedback → Autonomous Systems\n\nThis interview is worth more than most $500 agent engineering courses\n\nBookmark and watch it today\n\nThen read the full harness engineering guide below ↓", "name": "reine", "handle": "reinexbt", "avatar": "https://pbs.twimg.com/profile_images/2106004523227529216/4JqcnzAr_200x200.jpg", "likes": 28, "rts": 2, "replies": 0, "views": 530, "ts": 1792593050, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112895941489360896/vid/avc1/642x360/9EogsfvNSYirN16Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112895941489360896/vid/avc1/1286x720/pbcldM3ajQ-CdhXo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112895941489360896/img/IjzgRr15vSBhfwNr.jpg", "dur": 1752}], "quote": {"id": "2093685107534000560", "url": "https://x.com/0xwhrrari/status/2093685107534000560", "text": "https://x.com/i/article/2093441687989186560", "name": "rari", "handle": "0xwhrrari", "avatar": "https://pbs.twimg.com/profile_images/2029005608125431808/RHmOjHaB_200x200.jpg", "likes": 1846, "rts": 308, "replies": 74, "views": 5107278, "ts": 1788008403, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.93, "thread": [], "tier": "skim"}, {"id": "2113019283047686227", "url": "https://x.com/NFL/status/2113019283047686227", "text": "10 🤝 1\n\n@insidetheNFL Week 6 Mic'd Up on X", "name": "NFL", "handle": "NFL", "avatar": "https://pbs.twimg.com/profile_images/1619895559334273028/PHKS_mjX_200x200.jpg", "likes": 3078, "rts": 248, "replies": 51, "views": 492175, "ts": 1792618029, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113018866683314176/vid/avc1/720x1280/JN9xH6SIoPUmuF7v.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113018866683314176/vid/avc1/1080x1920/PGMlv-jpc3RL1ZlG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113018866683314176/img/2NVR4CGoJoqcMxpp.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.93, "thread": [], "tier": "skim"}, {"id": "2112905676263461100", "url": "https://x.com/givros/status/2112905676263461100", "text": "I asked GPT-6.1 Sol Light to build a Cozy Alpine Lake \n\nMy workflow:\n1.Describe the scene I have in mind to ChatGPT.\n2.Ask ChatGPT to write a detailed prompt, with strict instructions to use only my custom skill.\n3.Give GPT-6.1 Sol Light the prompt + reference image.\n4.Finish my FIFA match.\n5.👇", "name": "Givros", "handle": "givros", "avatar": "https://pbs.twimg.com/profile_images/2058488850125586434/hqfZ8XHV_200x200.jpg", "likes": 22, "rts": 3, "replies": 2, "views": 1640, "ts": 1792590943, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112905388009947136/vid/avc1/1280x720/24HWRQNI82RwMgvE.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112905388009947136/vid/avc1/1920x1080/bKclBXiwC1Ctrja6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112905388009947136/img/BJcgiO8bdwzUnoxO.jpg", "dur": 62}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVKMfSWXcAAtfSK.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.93, "thread": [], "tier": "skim"}, {"id": "2112906776349954326", "url": "https://x.com/0xSoural/status/2112906776349954326", "text": "Holy f*ck, Claude Opus 5.5 just animated my entire iPhone in 3D.\n\nNo After Effects. No Blender. No keyframes. Just one prompt...\n\nDrop the prompt below into Opus 5.5 and see what it makes\n\nP.S: Motion studios charge $5,000 for a 25 second film like this", "name": "soural", "handle": "0xSoural", "avatar": "https://pbs.twimg.com/profile_images/2100593651818676224/3pM1Fnq2_200x200.jpg", "likes": 22, "rts": 2, "replies": 3, "views": 1480, "ts": 1792591206, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112904855861841920/vid/avc1/1280x720/T_fKXxAFmyWljyC2.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112904855861841920/vid/avc1/1920x1080/7kAr2WpEFenLAyXD.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112904855861841920/img/yv2wsz9m1HIlNQXu.jpg", "dur": 24}], "quote": {"id": "2112533459604328479", "url": "https://x.com/0xSoural/status/2112533459604328479", "text": "Claude Opus 5.5 could be the last motion design tool you ever pay for\n\nNo After Effects. It writes every frame, checks its own stills and fixes them by frame number\n\nIn this article, I show you how, with every prompt https://x.com/i/article/2112524052988391425", "name": "soural", "handle": "0xSoural", "avatar": "https://pbs.twimg.com/profile_images/2100593651818676224/3pM1Fnq2_200x200.jpg", "likes": 23, "rts": 2, "replies": 3, "views": 4213, "ts": 1792502200, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.92, "thread": [], "tier": "skim"}, {"id": "2112975903512756252", "url": "https://x.com/SofiaTachExpert/status/2112975903512756252", "text": "I watched the whole thread twice.\n\nAgents ordering Uber, buying on Amazon, reacting to flight delays, scrolling TikTok and doing 2FA - all through a real phone.\n\nThis isn’t a tool. This is agents finally living in the same world as us.\n\nEarly access feels like finding the real alpha.", "name": "SOFIA", "handle": "SofiaTachExpert", "avatar": "https://pbs.twimg.com/profile_images/2106490860787372032/KlhsXLWg_200x200.jpg", "likes": 19, "rts": 0, "replies": 4, "views": 901, "ts": 1792607687, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112975820796878848/vid/avc1/1280x720/G6N4KRLjHNrk5m08.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112975820796878848/vid/avc1/1920x1080/wuOHPw96MZ79V3Is.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112975820796878848/img/gzyY8AQXZKYftBQa.jpg", "dur": 9}], "quote": {"id": "2112971597648978044", "url": "https://x.com/abdullababakre/status/2112971597648978044", "text": "defining a new category: phone-use\n\nan mcp/api that gives ai agents their own phones\n\ncloud phones. real androids. real iphones.\n\ntell your agent what to do, and it can operate a phone just like you do.\n\ntoday, ai agents face three fundamental problems and phoneuse solves them 🧵", "name": "Abdulla Ababakre", "handle": "abdullababakre", "avatar": "https://pbs.twimg.com/profile_images/2090009952249360384/FDXnxT-V_200x200.jpg", "likes": 1357, "rts": 125, "replies": 231, "views": 729947, "ts": 1792606660, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112970511634567168/vid/avc1/1280x720/4th34JxyLqmEKfq5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112970511634567168/vid/avc1/1920x1080/8t5XPElUmfeSyPa7.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112970511634567168/img/WFKbCE_aJcTG4pJ5.jpg", "dur": 46}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.92, "thread": [], "tier": "skim"}]);